CREATE OR ALTER PROCEDURE [dbo].[uspMealWasteRecord_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @ProductionOrderId UNIQUEIDENTIFIER = NULL
	, @DishId UNIQUEIDENTIFIER = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @WasteType NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionBatchId]
			, t.[ProductionOrderId]
			, t.[DishId]
			, t.[ShiftId]
			, t.[WasteType]
			, t.[QuantityMeals]
			, t.[QuantityKg]
			, t.[Reason]
			, t.[Disposition]
			, t.[OccurredAt]
			, t.[RecordedBy]
			, t.[CreatedDate]
		FROM [dbo].[MealWasteRecord] AS t
		
		WHERE 1 = 1
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (@ProductionOrderId IS NULL OR t.[ProductionOrderId] = @ProductionOrderId)
			AND (@DishId IS NULL OR t.[DishId] = @DishId)
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (ISNULL(@WasteType, '') = '' OR t.[WasteType] = @WasteType)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishId' THEN r.[DishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishId' THEN r.[DishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'wasteType' THEN r.[WasteType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'wasteType' THEN r.[WasteType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantityMeals' THEN r.[QuantityMeals] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantityMeals' THEN r.[QuantityMeals] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantityKg' THEN r.[QuantityKg] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantityKg' THEN r.[QuantityKg] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reason' THEN r.[Reason] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reason' THEN r.[Reason] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'disposition' THEN r.[Disposition] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'disposition' THEN r.[Disposition] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'occurredAt' THEN r.[OccurredAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'occurredAt' THEN r.[OccurredAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
